function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 5 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value of nums is an integer from -10^5 to 10^5.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 50000) return 'queries needs 1 to 5 * 10^4 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2 || !query.every(Number.isInteger)) return 'Each query is a pair [pos, x].';
    if (query[0] < 0 || query[0] >= nums.length) return 'Each pos must be an index of nums.';
    if (query[1] < -100000 || query[1] > 100000) return 'Each x is between -10^5 and 10^5.';
  }
  return null;
}

