function maximumSumSubsequence(nums, queries) {
  const MOD = 1000000007;
  const n = nums.length;
  // tree[node] summarises the node's range: its best sum with no restriction (full),
  // or with its first element, its last element, or both left out.
  const tree = new Array(4 * n);

  function leaf(value) {
    return { full: Math.max(0, value), skipFirst: 0, skipLast: 0, skipBoth: 0 };
  }

  // The last element of left and the first element of right are neighbours: one of them stays out.
  function merge(left, right) {
    return {
      full: Math.max(left.skipLast + right.full, left.full + right.skipFirst),
      skipFirst: Math.max(left.skipBoth + right.full, left.skipFirst + right.skipFirst),
      skipLast: Math.max(left.skipLast + right.skipLast, left.full + right.skipBoth),
      skipBoth: Math.max(left.skipBoth + right.skipLast, left.skipFirst + right.skipBoth),
    };
  }

  function build(node, start, end) {
    if (start === end) {
      tree[node] = leaf(nums[start]);
      return;
    }
    const mid = Math.floor((start + end) / 2);
    build(2 * node, start, mid);
    build(2 * node + 1, mid + 1, end);
    tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
  }

  function update(node, start, end, pos, value) {
    if (start === end) {
      tree[node] = leaf(value);
      return;
    }
    const mid = Math.floor((start + end) / 2);
    if (pos <= mid) {
      update(2 * node, start, mid, pos, value);
    } else {
      update(2 * node + 1, mid + 1, end, pos, value);
    }
    tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
  }

  build(1, 0, n - 1);
  let total = 0;
  for (const [pos, x] of queries) {
    update(1, 0, n - 1, pos, x);
    total = (total + tree[1].full) % MOD;
  }
  return total;
}

