function maximumSumSubsequence(nums, queries) {
  // Apply each update to a copy and rerun the take-or-skip DP over the whole array.
  const values = nums.slice();
  let total = 0;
  for (const [pos, x] of queries) {
    values[pos] = x;
    let taken = -Infinity; // best total whose last examined element is picked
    let skipped = 0; // best total whose last examined element is not picked
    for (const v of values) {
      [taken, skipped] = [skipped + v, Math.max(taken, skipped)];
    }
    total = (total + Math.max(taken, skipped)) % 1000000007;
  }
  return total;
}

