function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  // Values with mixed signs, mostly negative or mostly positive; small inputs often use tiny values.
  const span = !large && rand() < 0.6 ? 10 : 100000;
  const [lo, hi] = [[-span, span], [-span, span / 5], [-span / 5, span]][int(0, 2)];
  const nums = Array.from({ length: n }, () => int(lo, hi));
  const count = large ? 2000 : int(1, 6);
  const queries = Array.from({ length: count }, () => [int(0, n - 1), int(lo, hi)]);
  return [nums, queries];
}
